def nextSameDigitSum(n):
    s = [0] + [int(c) for c in str(n)]
    L = len(s)
    total = sum(s)
    pref = [0] * (L + 1)
    for i in range(L):
        pref[i + 1] = pref[i] + s[i]
    for i in range(L - 1, -1, -1):
        rem = L - i - 1
        for d in range(s[i] + 1, 10):
            need = total - pref[i] - d
            if 0 <= need <= 9 * rem:
                tail = []
                left = need
                for j in range(rem):
                    slots_after = rem - j - 1
                    for c in range(10):
                        if 0 <= left - c <= 9 * slots_after:
                            tail.append(c)
                            left -= c
                            break
                return int(''.join(map(str, s[:i] + [d] + tail)))
    return -1
